"""Build the declarative method catalogue; acceptance status is explicit."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def p(label,kind,default,**kw):return dict(label=label,type=kind,default=default,**kw)
def enum(label,default,choices):return p(label,'enum',default,choices=[dict(id=a,label=b) for a,b in choices])
def rec(identity,label,description,parameters=None,stage='B',cost='Veri ve kat sayısıyla artar.'):
    return dict(id=identity,label=label,description=description,parameters=parameters or {},stage=stage,enabled=False,status='acceptance_pending' if stage=='B' else 'not_implemented',reason='Kabul sınamaları sürüyor.' if stage=='B' else 'Bu aşama henüz uygulanmadı.',cost=cost)

def main():
    cats={}
    validation_params={'n_splits':p('Dış kat sayısı','int',5,min=2,max=50),'inner_splits':p('İç kat sayısı','int',3,min=2,max=20),'repeats':p('Tekrar sayısı','int',1,min=1,max=100),'seed':p('Rastgelelik tohumu','int',42,min=0,max=2147483646),'block_size':p('Blok boyutu (m)','float',1000,min=1,max=1000000),'buffer_distance':p('Tampon uzaklığı (m)','float',0,min=0,max=1000000),'metric_crs':p('Metrik koordinat sistemi','string',''),'min_train_groups':p('Asgari eğitim grubu','int',2,min=2,max=10000),'inner_method':enum('Özel katlarda iç ayırma','group',[('group','Gruplu'),('random','Rastgele'),('spatial_block','Mekânsal bloklu'),('buffered','Tamponlu')])}
    cats['validation']=[rec(i,l,d,validation_params) for i,l,d in [('random','Rastgele k-katlı','Bağımlı grupları ayırmaz; böyle veri varsa gruplu yöntemi seçin.'),('repeated','Tekrarlı rastgele k-katlı','Her tekrar ayrı değerlendirilir; tahmin sayısı bağımsız örnek sayısı değildir.'),('group','Gruplu k-katlı','Profil, parsel ve işletme ilişkileriyle bağlı gözlemler birlikte tutulur.'),('spatial_block','Mekânsal bloklu','Metrik grid blokları katlara atanır. Alan doğruluğunun yansız tahmini değildir.'),('buffered','Tamponlu mekânsal','Test bloklarına tampon uzaklığından yakın eğitim grupları çıkarılır.'),('custom','Kullanıcı tanımlı katlar','Kimlik kapsamı, grup ve uzaklık koşulları yine denetlenir.')]]
    cats['validation'] += [rec('knndm','En yakın komşu uzaklığı eşleme','Özgün CAST uygulamasıyla karşılaştırma gerekir.',stage='C'),rec('environmental','Çevresel kümeler','Çevresel aktarımın ayrıca sınanması gerekir.',stage='C'),rec('temporal','Zamansal ayırma','Tarih ve ileri zaman görevi ayrı doğrulanır.',stage='D'),rec('design_based','Olasılıklı alan doğrulaması','Örnekleme tasarımına uygun ağırlıklı tahminci henüz uygulanmadı.',stage='separate')]
    cats['preprocessing']=[rec('standard_pipeline','Ön işleme','Her işlem yalnız ilgili eğitim gözlemlerinde öğrenilir.',{'imputation':enum('Eksik girdi','median',[('none','İşlem yok'),('median','Medyan'),('knn','En yakın komşu')]),'scaling':enum('Ölçekleme','standard',[('none','İşlem yok'),('standard','Standart'),('robust','Dayanıklı')]),'unknown_category':enum('Bilinmeyen kategori','flag',[('error','Durdur'),('flag','İşaretle')]),'knn_neighbors':p('Komşu sayısı','int',5,min=1,max=100)})]
    cats['target_transform']=[rec('none','Dönüşüm yok','Özgün hedef biriminde eğitim.'),rec('log','Logaritmik dönüşüm','Yalnız pozitif hedef. Geri dönüşüm büyüklüğü önceden seçilir.',{'log_estimand':enum('Haritalanan büyüklük','median',[('median','Üstel geri dönüşüm'),('mean_smearing','Eğitim artıklarından ortalama düzeltmesi')])}),rec('yeo_johnson','Yeo-Johnson dönüşümü','Dönüşüm katsayısı yalnız eğitimde öğrenilir.')]
    vp={'threshold':p('Eleme eşiği','float',10,min=1.01,max=100000),'protected_ids':p('Korunacak değişken kimlikleri','ids',[]),'priority_ids':p('Önce elenecek değişken kimlikleri','ids',[])}
    cats['vif']=[rec('off','Kapalı','Çoklu bağlantı tanısı yapılmaz.'),rec('diagnostic','Yalnız tanı','Varyans şişirme faktörü, açıklayıcı değişkenler arasındaki bağlantıyı ölçer. Eleme yapmaz.',vp),rec('iterative','İteratif eleme','Eşiği aşan sürekli değişkenler eğitim içinde sırayla elenir. Kategorik gösterge sütunları parçalanmaz.',vp)]
    selectors=[('none','Seçim yok','Bütün seçilmiş girdileri kullanır.'),('pearson','Pearson filtresi','Yüksek doğrusal bağlantılı değişkenleri eğitimde eler.'),('spearman','Spearman filtresi','Sıralama bağlantısını eğitimde değerlendirir.'),('mutual_info','Karşılıklı bilgi','Girdinin hedef toprak özelliğiyle doğrusal olmayan bağımlılığını eğitimde ölçer.'),('elastic_net','Elastic Net ile seçim','Seçici doğrusal modeli nihai modelden ayrıdır.'),('sfs','Ardışık ileri seçim','Her altkatta ön işleme yeniden öğrenilir. Hesaplama maliyeti yüksektir.'),('rfe','Özyinelemeli eleme','Katsayı veya ağaç önemine uygun model gerekir.'),('boruta','Boruta','İlişkili değişkenleri arar. En küçük en iyi modeli garanti etmez.'),('pca','Temel bileşenler analizi','Eğitimde öğrenilen dönüşümdür; değişken seçimi değildir.')]
    sp={'k':p('Değişken / bileşen sayısı','int',1,min=1,max=256),'threshold':p('Bağlantı eşiği','float',0.9,min=0.01,max=1),'protected_ids':p('Korunacak kimlikler','ids',[]),'priority_ids':p('Eleme önceliği','ids',[])}
    sp['compare_without_selection']=p('Seçim yapılmamış karşılığıyla karşılaştır','bool',False)
    cats['feature_selection']=[rec(i,l,d,{} if i=='none' else sp) for i,l,d in selectors]
    tree={'n_estimators':p('Ağaç sayısı','int',100,min=10,max=2000),'max_depth':p('Azami derinlik','int',10,min=1,max=100),'min_samples_leaf':p('Yapraktaki asgari gözlem','int',2,min=1,max=100),'max_features':p('Değişken oranı','float',1.0,min=0.01,max=1)}
    cats['model']=[rec('mean','Eğitim ortalaması','Eğitim hedefi ortalamasını karşılaştırıcı olarak kullanır.'),rec('median','Eğitim medyanı','Eğitim hedefi medyanını karşılaştırıcı olarak kullanır.'),rec('ridge','Ridge regresyonu','Katsayıları küçülten doğrusal regresyon.',{'alpha':p('Düzenlileştirme katsayısı','float',1,min=0.000001,max=1000000)}),rec('elastic_net','Elastic Net regresyonu','İki düzenlileştirme cezasını birleştirir.',{'alpha':p('Düzenlileştirme katsayısı','float',1,min=0.000001,max=1000000),'l1_ratio':p('Birinci cezanın oranı','float',0.5,min=0,max=1),'max_iter':p('Azami yineleme','int',10000,min=100,max=100000)}),rec('random_forest','Rastgele orman','Eğitim örneklerinden ağaç topluluğu kurar.',tree),rec('extra_trees','Aşırı rastgeleleştirilmiş ağaçlar','Rastgele bölme noktalarıyla ağaç topluluğu kurar.',tree),rec('svr','Destek vektör regresyonu','Çekirdek yöntemiyle regresyon. Büyük örneklemde maliyetlidir.',{'C':p('Ceza katsayısı','float',1,min=0.000001,max=1000000),'epsilon':p('Hata toleransı','float',0.1,min=0,max=10000),'kernel':enum('Çekirdek','rbf',[('rbf','Radyal'),('linear','Doğrusal')]),'gamma':enum('Çekirdek ölçeği','scale',[('scale','Varyansa göre'),('auto','Değişken sayısına göre')])}),rec('hist_gradient_boosting','Histogram tabanlı gradyan artırma','Erken durdurma kapalı; yineleme sayısı iç katlarda seçilir.',{'max_iter':p('Yineleme','int',100,min=10,max=2000),'max_leaf_nodes':p('Yaprak sayısı','int',31,min=2,max=255),'learning_rate':p('Öğrenme oranı','float',0.1,min=0.0001,max=1),'min_samples_leaf':p('Yapraktaki asgari gözlem','int',10,min=1,max=100)}),rec('xgboost','XGBoost','İşlemci üzerinde artırmalı ağaçlar. Erken durdurma kapalı.',{'n_estimators':p('Ağaç sayısı','int',100,min=10,max=2000),'max_depth':p('Derinlik','int',6,min=1,max=20),'learning_rate':p('Öğrenme oranı','float',0.1,min=0.0001,max=1),'subsample':p('Gözlem oranı','float',1,min=0.1,max=1),'colsample_bytree':p('Değişken oranı','float',1,min=0.1,max=1)})]
    for i,l in [('lightgbm','LightGBM'),('catboost','CatBoost'),('cubist','Cubist'),('ordinary_kriging','Adi kriging'),('regression_kriging','Regresyon-kriging')]:cats['model'].append(rec(i,l,'Ayrı bağımlılık ve yöntem kabulü gerekir.',stage='C'))
    for i,l in [('tabpfn','TabPFN'),('tabm','TabM'),('realmlp','RealMLP')]:cats['model'].append(rec(i,l,'Deneysel model; lisans, sürüm ve yerel çalışma sınanmalıdır.',stage='D'))
    op={'trials':p('Deneme bütçesi','int',10,min=1,max=10000),'timeout_seconds':p('Süre bütçesi (s)','int',300,min=1,max=86400),'seed':p('Tohum','int',42,min=0,max=2147483646),'metric':enum('Birincil hata ölçütü','rmse',[('rmse','Ortalama kare hatanın karekökü'),('mae','Ortalama mutlak hata')]),'n_jobs':p('Eşzamanlı iş','int',1,min=1,max=1)}
    cats['optimization']=[rec(i,l,d,op) for i,l,d in [('manual','Manuel','Önceden belirlenmiş ayarları aynı iç katlarda değerlendirir.'),('grid','Izgara araması','Sonlu aday ayarların tamamını bütçe içinde değerlendirir.'),('random','Rastgele arama','Tanımlanan aralıklardan bütçe kadar aday alır.'),('optuna','Optuna','Ağaç yapılı Parzen kestiricisi önceki denemelerden yeni ayarlar seçer. Küresel en iyi sonucu garanti etmez.')]]
    up={'coverage':p('Nominal kapsama','float',0.9,min=0.5,max=0.99),'calibration_fraction':p('Kalibrasyon oranı','float',0.25,min=0.05,max=0.5),'quantile_model':enum('Kantil modeli','quantile_forest',[('quantile_forest','Kantil regresyon ormanı'),('quantile_boosting','Kantil kayıplı gradyan artırma')])}
    cats['uncertainty']=[rec(i,l,d,{} if i=='none' else up) for i,l,d in [('none','Aralık yok','Yalnız nokta tahmini.'),('split_conformal','Bölünmüş konformal','Ayrı kalibrasyon gözlemlerinin mutlak hatalarıyla aralık kurar.'),('quantile_forest','Kantil regresyon ormanı','Rastgele orman ailesinde gerçek koşullu kantiller. Kalibrasyonsuz kapsam dış katlarda sınanır.'),('quantile_boosting','Kantil kayıplı gradyan artırma','Histogram ailesinde ayrı alt ve üst kantil modelleri.'),('cqr','Konformalize kantil regresyonu','Kantil aralığını ayrı kalibrasyon verisiyle düzeltir.')]]
    cats['uncertainty'] += [rec('group_bootstrap','Grup bootstrap yayılımı','Modelleme değişkenliğidir; gözlem tahmin aralığı değildir.',stage='C'),rec('spatial_conformal','İleri mekânsal konformal','Yönteme özgü varsayım ve ayrı kabul gerekir.',stage='D')]
    obj={'schema_version':1,'registry_version':'0.2.0-dev','categories':cats}
    dest=ROOT/'backend/sps/registry.json';dest.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(dest)
if __name__=='__main__':main()
